const body = $input.first().json.body || $input.first().json;
const jobId = body.job_id || 'auto';
const rawUrl = (body.aff_url || '').trim();
const sep = rawUrl.includes('?') ? '&' : '?';
const fbUtmUrl = rawUrl ? `${rawUrl}${sep}utm_source=fb_reels&utm_medium=pinned_comment&utm_campaign=job_${jobId}` : '';
const ytUtmUrl = rawUrl ? `${rawUrl}${sep}utm_source=yt_shorts&utm_medium=description&utm_campaign=job_${jobId}` : '';

// Strip any raw URLs from FB Reels caption to prevent reach penalty (Brand Guidelines 4.3)
const cleanCaption = (body.caption || body.title || 'Đồ tiện ích thông minh đáng thử').replace(/https?:\/\/\S+/g, '').trim();
const fbCaption = `${cleanCaption}\n\n👉 Link sản phẩm tui ghim ở bình luận đầu tiên nha!`;
const fbPinnedComment = fbUtmUrl ? `🔥 Chốt đơn chính hãng giá hời tại đây nha các bác: ${fbUtmUrl}` : '🔥 Link sản phẩm đang cập nhật ở đầu kênh nha!';

// YT Shorts title < 60 chars + 3 hashtags
const baseTitle = (body.title || 'Món đồ tiện ích cứu cánh mỗi ngày').slice(0, 35).trim();
const ytTitle = `${baseTitle} #Shorts #TienIch #Review`;
const ytDescription = `${cleanCaption}\n\n👉 Chi tiết món này tui để ở đây và Link bio đầu kênh nhé: ${ytUtmUrl}`;

// Golden hour slot selection (11:45 or 20:00)
const slot = body.schedule_slot === '20:00' ? '20:00' : '11:45';

return [{
  json: {
    status: 'READY_FOR_PUBLISH_QUEUE',
    job_id: jobId,
    product_id: body.product_id || 1,
    video_path: body.video_path,
    schedule_slot: slot,
    approval_gate: body.approval_status || 'DRAFT_ONLY',
    channels: {
      facebook_reels: {
        caption_no_link: fbCaption,
        pinned_comment_with_link: fbPinnedComment,
        tracked_aff_url: fbUtmUrl
      },
      youtube_shorts: {
        title_under_60_chars: ytTitle,
        title_length: ytTitle.length,
        description: ytDescription,
        tracked_aff_url: ytUtmUrl
      }
    },
    processed_at: new Date().toISOString()
  }
}];

const body = $input.first().json.body || $input.first().json;
return [{
  json: {
    status: 'PRODUCT_ALERT_LOGGED',
    product_name: body.name || 'Unknown SKU',
    score: body.score || 0,
    commission: body.commission || 'N/A',
    hook_angle: body.hook_angle || '',
    alert_message: `🎯 [WINNING SKU] ${body.name || 'SKU'} (Score: ${body.score || 0}/100 | HH: ${body.commission || 'N/A'}) - Hook: ${body.hook_angle || ''}`,
    processed_at: new Date().toISOString()
  }
}];

const body = $input.first().json.body || $input.first().json;
const views = Number(body.views || 0);
const clicks = Number(body.clicks || 0);
const orders = Number(body.orders || 0);
const ctr = views > 0 ? Number(((clicks / views) * 100).toFixed(2)) : 0;
const cvr = clicks > 0 ? Number(((orders / clicks) * 100).toFixed(2)) : 0;
const decision = orders > 0 && ctr >= 1.5 ? 'KEEP_AND_SCALE' : (views >= 1000 && ctr < 0.8 ? 'ITERATE_HOOK_CTA' : 'MONITOR');
return [{
  json: {
    status: 'ANALYTICS_SYNCED',
    job_id: body.job_id || 0,
    metrics: { views, clicks, orders, ctr_pct: ctr, cvr_pct: cvr },
    recommendation: decision,
    processed_at: new Date().toISOString()
  }
}];
